package com.finsightai;import com.finsightai.model.Transaction;import com.finsightai.repository.TransactionRepository;import com.finsightai.service.AnalyticsService;import org.junit.jupiter.api.*;import org.mockito.Mockito;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;import org.springframework.data.jpa.domain.Specification;import static org.junit.jupiter.api.Assertions.*;
class AnalyticsServiceTest{@Test void kpisShouldCalculateProfit(){TransactionRepository repo=Mockito.mock(TransactionRepository.class);Transaction i=new Transaction();i.setType("INCOME");i.setAmount(BigDecimal.valueOf(1000));i.setTransactionDate(LocalDate.now());Transaction e=new Transaction();e.setType("EXPENSE");e.setAmount(BigDecimal.valueOf(300));e.setTransactionDate(LocalDate.now());Mockito.when(repo.findAll()).thenReturn(List.of(i,e));Mockito.when(repo.count(Mockito.any(Specification.class))).thenReturn(0L);var r=new AnalyticsService(repo).kpis();assertEquals(BigDecimal.valueOf(700),r.profit());assertEquals(70.0,r.margin());}}
